// Classificacao de urgencia para avisos de WhatsApp no Slack (decisao de negocio 21/09/2026).
// Fonte unica da lista de palavras-chave: este sub-workflow e chamado por WhatsApp_Webhook_Status e Sub_Escalar_Atendimento_IA.
const PALAVRAS = ['proposta', 'formulario', 'duvida'];
const norm = s => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
const texto = norm($input.first().json.texto);
const palavra = PALAVRAS.find(p => texto.includes(p)) || '';
const urgente = palavra !== '';
return [{ json: { urgente, palavra, prefixo: urgente ? ('🔴 URGENTE (palavra: ' + palavra + ') — ') : '' } }];
